<?php
if(PHP_SAPI!=='cli')exit;require __DIR__.'/../core/init.php';session_save_path(sys_get_temp_dir());session_start();$u=sc_query('SELECT userid FROM users WHERE user_group=1 AND is_active=1 AND is_deleted=0 LIMIT 1')->get_result()->fetch_assoc();$_SESSION[USER_AUTH]=$u['userid'];$csrf=sc_csrf();$keys=['festive_enabled','festive_festival','festive_intensity','festive_greeting'];$original=[];foreach($keys as $key)$original[$key]=sc_query('SELECT id,value FROM systemv WHERE variable=?','s',[$key])->get_result()->fetch_all(MYSQLI_ASSOC);$audit=[];$last=[];$tag='SC festive test '.bin2hex(random_bytes(3));
function fverify($v,$label){if(!$v)throw new RuntimeException($label);echo 'PASS '.$label."\n";}
function saveFixture($input){global $csrf,$audit,$last;sc_save_festival(['csrf'=>$csrf,...$input]);$audit[]=sc_db()->insert_id;$last=['festive_enabled'=>isset($input['enabled'])?'1':'0','festive_festival'=>$input['festival'],'festive_intensity'=>$input['intensity'],'festive_greeting'=>$input['greeting']??''];}
try {
foreach(['holi','diwali','eid','bakr_eid','christmas','dussehra','new_year','easter'] as $key)fverify(isset(sc_festivals()[$key]),'festival available: '.$key);
saveFixture(['festival'=>'holi','intensity'=>'low','greeting'=>$tag]);$html=file_get_contents(sc_url());fverify(!str_contains($html,'id="sc-festive"'),'disabled mode adds no public effect markup');$html=file_get_contents(sc_url('?festive_preview=diwali'));fverify(!str_contains($html,'id="sc-festive"'),'anonymous visitors cannot enable preview');
saveFixture(['enabled'=>'1','festival'=>'holi','intensity'=>'medium','greeting'=>$tag.' <script>unsafe()</script>']);$html=file_get_contents(sc_url());fverify(str_contains($html,'id="sc-festive"')&&str_contains($html,'sc-festive-holi'),'enabled Holi rendered on homepage');fverify(!str_contains($html,'<script>unsafe()</script>'),'custom greeting is escaped');preg_match('/data-config="([^"]+)"/',$html,$m);$config=json_decode(html_entity_decode($m[1],ENT_QUOTES,'UTF-8'),true);fverify($config['effect']==='splash'&&$config['intensity']==='medium','client receives validated festival configuration');
saveFixture(['enabled'=>'1','festival'=>'diwali','intensity'=>'low','greeting'=>$tag]);$html=file_get_contents(sc_url());fverify(str_contains($html,'sc-rocket-launch')&&str_contains($html,'sc-diya'),'Diwali includes rocket launcher and diyas');$html=file_get_contents(sc_url('products'));fverify(!str_contains($html,'id="sc-festive"'),'effects are limited to homepage');
$bad=false;try{sc_save_festival(['csrf'=>'bad','festival'=>'holi','intensity'=>'low']);}catch(RuntimeException $e){$bad=true;}fverify($bad,'festival settings reject invalid CSRF');
$bad=false;try{sc_save_festival(['csrf'=>$csrf,'festival'=>'unknown','intensity'=>'low']);}catch(RuntimeException $e){$bad=true;}fverify($bad,'unknown festival rejected');
$menu=file_get_contents(__DIR__.'/../admin/components/contextMenu.php');fverify(!str_contains($menu,"createNew('page')")&&!str_contains($menu,"createNew('menu')")&&str_contains($menu,'Private follow-up'),'context shortcuts remove page/menu creation and include follow-ups');
}finally{
foreach($keys as $key){if(!$last)continue;if($original[$key]){foreach($original[$key] as $row)sc_query('UPDATE systemv SET value=? WHERE id=? AND value=?','sis',[$row['value'],$row['id'],$last[$key]]);}else sc_query('DELETE FROM systemv WHERE variable=? AND value=?','ss',[$key,$last[$key]]);}foreach($audit as $id)sc_query('DELETE FROM admin_updates WHERE id=? AND update_text=?','is',[$id,'[admin] festive_mode.updated']);session_destroy();echo "Original festive settings restored.\n";
}
